//! Checks the reader and writer against `fixtures/datalog.wpilog`, which WPILib's own Java
//! `DataLogWriter` wrote (generated by the Java `DataLogFixtures` before the Rust cutover).

use std::path::Path;
use std::sync::{Arc, Mutex};
use telemetry::datalog::{Config, DataLog};
use telemetry::reader::{Control, Log, Reader, decode};
use wpilib::nt::Struct;
use wpimath::geometry::{Pose2d, Pose3d, Rotation2d};

fn fixture() -> Vec<u8> {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/datalog.wpilog");
    std::fs::read(path).expect("fixtures/datalog.wpilog")
}

#[test]
fn reads_every_entry_the_java_writer_made() {
    let log = Log::parse(&fixture()).unwrap();
    assert_eq!(log.extra_header, "");
    assert_eq!(
        log.names(),
        [
            "/Robot/bool",
            "/Robot/int",
            "/Robot/float",
            "/Robot/double",
            "/Robot/string",
            "/Robot/raw",
            "/Robot/boolArr",
            "/Robot/intArr",
            "/Robot/floatArr",
            "/Robot/doubleArr",
            "/Robot/stringArr",
            "/Robot/pose",
            "/.schema/struct:Translation2d",
            "/.schema/struct:Rotation2d",
            "/.schema/struct:Pose2d",
            "/Robot/pose3d",
            "/.schema/struct:Translation3d",
            "/.schema/struct:Quaternion",
            "/.schema/struct:Rotation3d",
            "/.schema/struct:Pose3d",
            "/Robot/poses",
        ]
    );
    let types: Vec<_> = log
        .entries
        .iter()
        .filter(|e| e.name.starts_with("/Robot/"))
        .map(|e| e.type_name.as_str())
        .collect();
    assert_eq!(
        types,
        [
            "boolean",
            "int64",
            "float",
            "double",
            "string",
            "raw",
            "boolean[]",
            "int64[]",
            "float[]",
            "double[]",
            "string[]",
            "struct:Pose2d",
            "struct:Pose3d",
            "struct:Pose2d[]",
        ]
    );
    for (i, entry) in log.entries.iter().enumerate() {
        assert_eq!(entry.id as usize, i + 1, "ids count up from 1");
    }
}

#[test]
fn reads_the_values_with_their_timestamps() {
    let log = Log::parse(&fixture()).unwrap();
    let get = |name: &str| log.entry(&format!("/Robot/{name}")).unwrap();

    let b = get("bool");
    assert_eq!(b.records, [(2000, vec![1]), (3000, vec![0])]);
    assert!(b.finished);
    assert_eq!(b.metadata, "{\"source\":\"DogLog\"}");

    assert_eq!(decode::int64(&get("int").records[0].1), Some(-42));
    assert_eq!(decode::float(&get("float").records[0].1), Some(1.5));

    let d = get("double");
    assert_eq!(d.records.len(), 2, "the repeat of 3.25 is skipped");
    assert_eq!(decode::double(&d.records[0].1), Some(3.25));
    assert_eq!(d.records[0].0, 2000);
    assert!(decode::double(&d.records[1].1).unwrap().is_nan());
    assert_eq!(d.records[1].0, 3000);
    assert_eq!(
        d.metadata_history,
        [
            "{\"source\":\"DogLog\",\"unit\":\"volts\"}",
            "{\"source\":\"DogLog\",\"unit\":\"amps\"}"
        ]
    );

    assert_eq!(decode::string(&get("string").records[0].1), "hello");
    assert_eq!(get("raw").records[0].1, [1, 2, 3]);
    assert_eq!(
        decode::boolean_array(&get("boolArr").records[0].1),
        [true, false, true]
    );
    assert_eq!(
        decode::int64_array(&get("intArr").records[0].1),
        Some(vec![1, -2, 300_000_000_000])
    );
    assert_eq!(
        decode::float_array(&get("floatArr").records[0].1),
        Some(vec![0.5, -0.25])
    );
    assert_eq!(
        decode::double_array(&get("doubleArr").records[0].1),
        Some(vec![1.0, 2.0, 3.0])
    );
    assert_eq!(
        decode::string_array(&get("stringArr").records[0].1),
        Some(vec!["a".to_owned(), "bc".to_owned(), String::new()])
    );
}

#[test]
fn struct_payloads_match_the_rust_packers() {
    let log = Log::parse(&fixture()).unwrap();
    let get = |name: &str| log.entry(&format!("/Robot/{name}")).unwrap();

    let mut want = Vec::new();
    Pose2d::from_xy(1.0, 2.0, Rotation2d::new(0.5)).pack(&mut want);
    assert_eq!(get("pose").records[0].1, want);

    let pose3d = Pose3d::unpack(&get("pose3d").records[0].1);
    assert_eq!(pose3d.translation.x, 1.0);
    assert_eq!(pose3d.translation.z, 3.0);
    let q = wpimath::geometry::Rotation3d::from_euler(0.1, 0.2, 0.3).quaternion();
    let got = pose3d.rotation.quaternion();
    for (a, b) in [(q.w, got.w), (q.x, got.x), (q.y, got.y), (q.z, got.z)] {
        assert!((a - b).abs() < 1e-12, "{a} vs {b}");
    }

    let poses = &get("poses").records[0].1;
    assert_eq!(poses.len(), 48);
    let mut want = Vec::new();
    Pose2d::from_xy(1.0, 0.0, Rotation2d::new(0.0)).pack(&mut want);
    Pose2d::from_xy(0.0, 1.0, Rotation2d::new(1.0)).pack(&mut want);
    assert_eq!(*poses, want);

    for (name, schema) in [
        ("Translation2d", "double x;double y"),
        ("Rotation2d", "double value"),
        ("Pose2d", "Translation2d translation;Rotation2d rotation"),
        ("Quaternion", "double w;double x;double y;double z"),
        ("Rotation3d", "Quaternion q"),
    ] {
        let entry = log.entry(&format!("/.schema/struct:{name}")).unwrap();
        assert_eq!(entry.type_name, "structschema");
        assert_eq!(entry.records[0].1, schema.as_bytes(), "{name}");
    }
}

#[test]
fn rust_schemas_match_the_ones_java_wrote() {
    let log = Log::parse(&fixture()).unwrap();
    let mut from_rust = Vec::new();
    Pose3d::add_schemas(&mut |n, s| from_rust.push((n.to_owned(), s.to_owned())));
    for (name, schema) in from_rust {
        let entry = log.entry(&format!("/.schema/struct:{name}")).unwrap();
        assert_eq!(entry.records[0].1, schema.as_bytes(), "{name}");
    }
}

/// Feeds every record of the Java file through the Rust writer. The output must be the same
/// bytes: same ids, same header sizes, same control records, same order.
#[test]
fn rust_writer_reproduces_the_java_file_byte_for_byte() {
    let java = fixture();
    let out = Arc::new(Mutex::new(Vec::new()));
    let sink = out.clone();
    let log = DataLog::new(Config::callback(move |b| {
        sink.lock().unwrap().extend_from_slice(b);
    }));

    let mut records = Reader::new(&java).unwrap().map(Result::unwrap);
    while let Some(record) = records.next() {
        match record.control() {
            Some(Control::Start {
                entry,
                name,
                type_name,
                metadata,
            }) => {
                if let Some(schema_name) = name.strip_prefix("/.schema/") {
                    let data = records.next().expect("a schema's data follows its start");
                    log.add_schema(schema_name, &type_name, data.payload, record.timestamp);
                } else {
                    let id = log
                        .start(&name, &type_name, &metadata, record.timestamp)
                        .unwrap();
                    assert_eq!(id, entry, "{name}");
                }
            }
            Some(Control::Finish { entry }) => log.finish(entry, record.timestamp),
            Some(Control::SetMetadata { entry, metadata }) => {
                log.set_metadata(entry, &metadata, record.timestamp);
            }
            None => log.append(record.entry, record.timestamp, record.payload),
        }
    }
    drop(log);

    let rust = out.lock().unwrap().clone();
    assert_eq!(rust.len(), java.len(), "file sizes");
    assert!(rust == java, "bytes differ");
}

#[test]
fn the_fixture_starts_with_the_spec_header() {
    let java = fixture();
    assert_eq!(java[..12], *b"WPILOG\x00\x01\x00\x00\x00\x00");
}
